// checks.js: the trainer's helper. Students do NOT edit this file.
// It loads each step file, tests it, and tells final.js which steps are done.
const path = require("path");

const APP = "My Bank";
const TOTAL = 10;
const STEPS = [
  { n: 1, file: './step01_header', title: 'Page title', day: 2, check: (f) => String(f()).includes('<h1') },
  { n: 2, file: './step02_name_box', title: 'Account holder name box', day: 2, check: (f) => String(f()).includes('name="name"') },
  { n: 3, file: './step03_create_account', title: 'Open an account', day: 2, check: (f) => (a => a && a.name === 'Ravi' && a.balance === 0)(f('Ravi')) },
  { n: 4, file: './step04_show_balance', title: 'Show the balance', day: 2, check: (f) => String(f({name:'R',balance:500})).includes('500') },
  { n: 5, file: './step05_deposit', title: 'Deposit money', day: 2, check: (f) => (a => { f(a, 200); return a.balance === 300; })({name:'R',balance:100}) },
  { n: 6, file: './step06_withdraw', title: 'Withdraw money', day: 3, check: (f) => (a => { f(a, 30); return a.balance === 70; })({name:'R',balance:100}) },
  { n: 7, file: './step07_enough_money', title: 'Stop if not enough money', day: 3, check: (f) => f({balance:100}, 50) === true && f({balance:100}, 500) === false },
  { n: 8, file: './step08_valid_amount', title: 'Stop zero or minus amounts', day: 3, check: (f) => f(100) === true && f(0) === false && f(-5) === false },
  { n: 9, file: './step09_history', title: 'Transaction history', day: 3, check: (f) => (h => { f(h, 'x'); return h.length === 1; })([]) },
  { n: 10, file: './step10_interest', title: 'Add 4% interest', day: 3, check: (f) => (a => { f(a); return a.balance === 1040; })({name:'R',balance:1000}) },
];

function load(n) {
  const s = STEPS[n - 1];
  const info = { n: s.n, title: s.title, file: s.file.slice(2) + ".js", day: s.day, f: null, status: "todo", err: "" };
  try {
    const full = require.resolve(path.join(__dirname, s.file));
    delete require.cache[full];
    const f = require(full);
    if (typeof f !== "function") throw new Error("module.exports was changed. Undo your change at the bottom of the file.");
    info.f = f;
    info.status = s.check(f) ? "done" : "todo";
  } catch (e) {
    info.status = "error";
    const m = String(e.stack || "").match(new RegExp(s.file.slice(2) + "\\.js:(\\d+)"));
    info.err = e.name + ": " + e.message + (m ? " (line " + m[1] + ")" : "");
  }
  return info;
}

function loadAll() {
  const all = {};
  for (let n = 1; n <= TOTAL; n++) all[n] = load(n);
  return all;
}

function run(n) {
  const s = load(n);
  console.log();
  if (s.status === "done") {
    console.log("  ✅  Step " + n + " done: " + s.title);
    console.log(n < TOTAL ? "      Refresh the browser page to see it. Then open step " + String(n + 1).padStart(2, "0") + "." : "      🎉 All steps finished!");
  } else if (s.status === "error") {
    console.log("  🔴  Step " + n + " has an error: " + s.err);
    console.log('      Check spelling, quotes " ", brackets ( ) { } and the ; at the end.');
  } else {
    console.log("  ❌  Step " + n + " not done yet: " + s.title);
    console.log("      Open " + s.file + ", type the line shown in the comment, save (Ctrl + S) and run this again.");
  }
  let done = 0;
  for (let k = 1; k <= TOTAL; k++) if (load(k).status === "done") done++;
  console.log("      Progress: " + done + " / " + TOTAL + " steps done");
  console.log();
}

module.exports = { APP, TOTAL, load, loadAll, run };
